  (* [comment removed for export] *)
  Definition meminv (m : mem) (j : list byte) (b0 l0 b1 l1 : word) : Prop :=
    rw_cells asegs m (usp + -112) (frame j b0 l0 b1 l1) /\
    rw_cells asegs m Fp (file_cells flags wend (B + zlength buf) B wfn B bufsize fd mode lbf tail) /\
    ro_cells asegs m got_ssp [C8 (Z_to_bv 64 ssp_guard)] /\ ro_cells asegs m ssp_guard [C8 canary] /\
    stk asegs m lo (usp + -112) /\ mem_inv asegs m /\ munch W m0 m /\ munch WF m0 m /\ wmono asegs m0 m.

